<?php
require __DIR__.'/../app/bootstrap.php'; admin(); require __DIR__.'/layout.php';
$statuses=['new','contacted','qualified','won','closed'];
$q=is_string($_GET['q']??null)?substr(trim($_GET['q']),0,190):'';
$status=in_array($_GET['status']??'', $statuses,true)?$_GET['status']:'';
$where='1=1'; $args=[];
if($q!=='') { $where.=' AND (name LIKE ? OR email LIKE ? OR company LIKE ? OR service LIKE ?)'; $args=array_fill(0,4,'%'.$q.'%'); }
if($status!=='') { $where.=' AND status=?'; $args[]=$status; }
$total=(int)query('SELECT COUNT(*) FROM leads WHERE '.$where,$args)->fetchColumn();
$pages=max(1,(int)ceil($total/20)); $page=max(1,min($pages,(int)($_GET['page']??1))); $offset=($page-1)*20;
$leads=query('SELECT * FROM leads WHERE '.$where.' ORDER BY id DESC LIMIT 20 OFFSET '.$offset,$args)->fetchAll();
$counts=array_fill_keys($statuses,0); foreach(query('SELECT status,COUNT(*) AS total FROM leads GROUP BY status') as $r) $counts[$r['status']]=(int)$r['total'];
page_start('Leads dashboard');
?><p class="muted">Every conversation starts here. Review enquiries and track the next step.</p><section class="stats"><?php foreach(['all'=>'Total enquiries','new'=>'New leads','qualified'=>'Qualified','won'=>'Won'] as $key=>$label): ?><div class="stat"><span><?=e($label)?></span><strong><?=$key==='all'?array_sum($counts):$counts[$key]?></strong><small><?=$key==='new'?'Ready for a first response':'Across all website enquiries'?></small></div><?php endforeach; ?></section><section class="panel"><div class="panel-head"><h2>Website enquiries</h2><span class="pill"><?=$total?> results</span></div><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search name, email, company or service" aria-label="Search leads"><select name="status" aria-label="Lead status"><option value="">All statuses</option><?php foreach($statuses as $s): ?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach; ?></select><button>Filter</button><a href="./">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Contact</th><th>Service</th><th>Status</th><th>Email alert</th><th>Received (UTC)</th><th></th></tr></thead><tbody><?php foreach($leads as $lead): ?><tr><td><strong><?=e($lead['name'])?></strong><small><?=e($lead['email'])?></small></td><td><?=e($lead['service'])?></td><td><span class="badge <?=e($lead['status'])?>"><?=e(ucfirst($lead['status']))?></span></td><td><?=e($lead['mail_status'])?></td><td><?=e($lead['created_at'])?></td><td><a href="lead.php?id=<?=$lead['id']?>">View →</a></td></tr><?php endforeach; ?><?php if(!$leads): ?><tr><td colspan="6" class="empty">No enquiries found. New contact form submissions will appear here.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if($page>1): ?><a href="?<?=e(http_build_query(['q'=>$q,'status'=>$status,'page'=>$page-1]))?>">← Previous</a><?php endif; ?><span>Page <?=$page?> of <?=$pages?></span><?php if($page<$pages): ?><a href="?<?=e(http_build_query(['q'=>$q,'status'=>$status,'page'=>$page+1]))?>">Next →</a><?php endif; ?></div></section><?php page_end(); ?>
